WITH exploded AS (SELECT id, host, log_ts, key, v FROM app_logs LATERAL VIEW EXPLODE(context) t AS key, v) SELECT DATE_TRUNC('HOUR', log_ts) AS hour_window, COUNT(DISTINCT key) AS distinct_keys, COUNT_IF(key = 'trace') AS trace_events, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS span_minutes FROM exploded GROUP BY DATE_TRUNC('HOUR', log_ts) HAVING (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 > 0;
